  },
  {
    "id": 226,
    "text": "うん、同じすぎる。",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 227,
    "text": "で、宿にこもってずっと本読んでで、今回はその景色がすごい綺麗だったからベランダでずっと川のせせらぎを聞きながら",
    "diarized": "Rina Honnizumi"
  },
  {
    "id": 228,
    "text": "ああ。",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 229,
    "text": "一緒すぎる。",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 230,
    "text": "似てるね。",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 231,
    "text": "ね。",
    "diarized": "Rina Honnizumi"
  },
  {
    "id": 232,
    "text": "癒され方がね。",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 233,
    "text": "ね。",
    "diarized": "Rina Honnizumi"
  },
  {
    "id": 234,
    "text": "わかる。",
    "diarized": "Rina Honnizumi"
  },
  {
    "id": 235,
    "text": "なんか時折水系を見たかったり浴びたかったり海も大好きなの。",
    "diarized": "Rina Honnizumi"
  },
  {
    "id": 236,
    "text": "浴びたい。",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 237,
    "text": "熱海とかちょいちょい行っちゃう。",
    "diarized": "Rina Honnizumi"
  },
  {
    "id": 238,
    "text": "近いから。",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 239,
    "text": "熱海よく行きます、私も。",
    "diarized": "Rina Honnizumi"
  },
  {
    "id": 240,
    "text": "北海道行きたくなってきた。",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 241,
    "text": "いいよ。",
    "diarized": "Rina Honnizumi"
  },
  {
    "id": 242,
    "text": "北海道の海も見たい。",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 243,
    "text": "素敵です、本当に。",
    "diarized": "Rina Honnizumi"
  },
  {
    "id": 244,
    "text": "うん。",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 245,
    "text": "船で行くのすごいありだなって思った。",
    "diarized": "Rina Honnizumi"
  },
  {
    "id": 246,
    "text": "飛行機代と宿代を合わせると船で行った方がもしかしてちょっと安いまであるぐらいでそう、",
    "diarized": "Rina Honnizumi"
  },
  {
    "id": 247,
    "text": "うん。",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 248,
    "text": "そうなんだ。",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 249,
    "text": "なんか船酔いさえしなければ海好きな人はめっちゃぴったりだと思います。",
