  },
  {
    "id": 605,
    "text": "最高。",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 606,
    "text": "なんかみんないいね。",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 607,
    "text": "大人だね。",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 608,
    "text": "自分はあまり暑さに強くなく、夏は用事以外であまり外に出る気にはなれないのですが外が涼しくなってくる秋になると散歩に出かけることが多いです。",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 609,
    "text": "うん。",
    "diarized": "Rina Honnizumi"
  },
  {
    "id": 610,
    "text": "その散歩の最中に見る、えー、紅葉や夕焼けなどがとても癒しになっています。",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 611,
    "text": "うん。",
    "diarized": "Rina Honnizumi"
  },
  {
    "id": 612,
    "text": "去年はあまり涼しいと感じる期間が短くあまり散歩していませんでしたので、",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 613,
    "text": "ねえ。",
    "diarized": "Rina Honnizumi"
  },
  {
    "id": 614,
    "text": "今年はいっぱい散歩できたらいいなと思っています。",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 615,
    "text": "ああ。",
    "diarized": "Rina Honnizumi"
  },
  {
    "id": 616,
    "text": "私も散歩大好き。",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 617,
    "text": "ああ。",
    "diarized": "Rina Honnizumi"
  },
  {
    "id": 618,
    "text": "もう普段からなるべく、や、もう確かに夏はあんまりねえ。",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 619,
    "text": "うん。",
    "diarized": "Rina Honnizumi"
  },
  {
    "id": 620,
    "text": "そうだよね。",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 621,
    "text": "暑いの私も苦手。",
    "diarized": "Rina Honnizumi"
  },
  {
    "id": 622,
    "text": "うん。",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 623,
    "text": "熱中症になっちゃうからね、気をつけててもね。",
    "diarized": "Rina Honnizumi"
  }
]

