    "diarized": "Rina Honnizumi"
  },
  {
    "id": 693,
    "text": "うん。",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 694,
    "text": "本番1ヶ月前くらいからはもう始まってる印象かな。",
    "diarized": "Rina Honnizumi"
  },
  {
    "id": 695,
    "text": "すごい。",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 696,
    "text": "自主練とかもするでしょう?",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 697,
    "text": "私はもうめちゃくちゃする。",
    "diarized": "Rina Honnizumi"
  },
  {
    "id": 698,
    "text": "1人でとにかく数こなそうって思っちゃう。",
    "diarized": "Rina Honnizumi"
  },
  {
    "id": 699,
    "text": "うん。",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 700,
    "text": "うん。",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 701,
