    "text": "しかもアイドルだしアイドルとしてキャラも成長してくから",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 704,
    "text": "うん。",
    "diarized": "Rina Honnizumi"
  },
  {
    "id": 705,
    "text": "エンジャンとしてはね、なんか頑張らなきゃって思うよね。",
    "diarized": "Rina Honnizumi"
  },
  {
    "id": 706,
    "text": "気合が入る。",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 707,
    "text": "この時期は。",
    "diarized": "Minori Suzuki"
  },
  {
    "id": 708,
    "text": "ありがたいよ。",
